import pandas as pd
import numpy as np

class BreakoutDetectionStrategy:
    def __init__(self, data):
        self.data = data
        self.vp_window = 20
        self.obv_window = 20
        self.ma_short_window = 50
        self.ma_long_window = 200
        self.risk_percentage = 0.02
        self.position_fraction = 0.1

    def calculate_indicators(self):
        self.data['vp'] = self.data['volume'].rolling(self.vp_window).mean()
        self.data['vp_avg'] = self.data['vp'].rolling(self.vp_window).mean()
        self.data['obv'] = self.data['volume'] * np.where(self.data['close'] > self.data['close'].shift(1), 1, -1)
        self.data['obv_avg'] = self.data['obv'].rolling(self.obv_window).mean()
        self.data['ma_short'] = self.data['close'].rolling(self.ma_short_window).mean()
        self.data['ma_long'] = self.data['close'].rolling(self.ma_long_window).mean()

    def generate_signals(self):
        signals = pd.DataFrame(index=self.data.index)
        signals['long'] = np.where((self.data['vp'] > self.data['vp_avg']) & (self.data['obv'] > self.data['obv'].shift(1)) & (self.data['ma_short'] > self.data['ma_long']), 1, 0)
        signals['short'] = np.where((self.data['vp'] < self.data['vp_avg']) & (self.data['obv'] < self.data['obv'].shift(1)) & (self.data['ma_short'] < self.data['ma_long']), -1, 0)
        return signals

    def calculate_positions(self, signals):
        positions = pd.DataFrame(index=self.data.index)
        positions['long'] = signals['long'].cumsum()
        positions['short'] = signals['short'].cumsum()
        return positions

    def calculate_pnl(self, positions):
        pnl = pd.DataFrame(index=self.data.index)
        pnl['long'] = positions['long'] * self.data['close']
        pnl['short'] = positions['short'] * self.data['close']
        return pnl

    def run_strategy(self):
        self.calculate_indicators()
        signals = self.generate_signals()
        positions = self.calculate_positions(signals)
        pnl = self.calculate_pnl(positions)
        return pnl

# Example usage
